define('core/digest',[],function () {
  'use strict';
  var subtle = window.crypto.subtle;
  var supportedAlgorithms = ['SHA-1', 'SHA-256', 'SHA-384', 'SHA-512'];
  function bufferToHexString(buffer) {
    return [...new Uint8Array(buffer)].map(val => "00".concat(val.toString(16)).slice(-2)).join('');
  }
  function digest(data) {
    var selectedAlgorithm = arguments.length > 1 && arguments[1] !== undefined ? arguments[1] : 'SHA-256';
    var algorithm = selectedAlgorithm.toUpperCase();
    if (!supportedAlgorithms.includes(algorithm)) {
      throw new TypeError("Unsupported digest algorithm : ".concat(algorithm));
    }
    var dataPromise;
    if (data instanceof Uint8Array) {
      dataPromise = Promise.resolve(data);
    } else if (data instanceof ArrayBuffer) {
      dataPromise = Promise.resolve(new Uint8Array([data]));
    } else if (data instanceof Blob) {
      dataPromise = new Promise((resolve, reject) => {
        var reader = new FileReader();
        reader.addEventListener('loadend', () => resolve(reader.result));
        reader.addEventListener('abort', reject);
        reader.addEventListener('error', reject);
        reader.readAsArrayBuffer(data);
      });
    } else if (typeof data === 'string') {
      dataPromise = Promise.resolve(new TextEncoder().encode(data));
    } else {
      throw new TypeError("Unsupported data type to digest with ".concat(algorithm));
    }
    return dataPromise.then(rawData => subtle.digest(algorithm, rawData)).then(buffer => bufferToHexString(buffer));
  }
  return digest;
});
