define('core/fetchRequest',['core/request/flowFactory'], function (httpRequestFlowFactory) {
  'use strict';

  httpRequestFlowFactory = httpRequestFlowFactory && Object.prototype.hasOwnProperty.call(httpRequestFlowFactory, 'default') ? httpRequestFlowFactory['default'] : httpRequestFlowFactory;
  var requestFactory = (url, options) => {
    options = Object.assign({
      timeout: 5000
    }, options);
    return httpRequestFlowFactory(fetch, url, options);
  };
  return requestFactory;
});
