define('core/encoder/entity',[],function () {
  'use strict';
  var guiltyChars = ['&', '<', '>', '"'];
  var entity = {
    encode(input) {
      input = "".concat(input);
      return input.split('').map(function (character) {
        return guiltyChars.indexOf(character) > -1 ? "&#".concat(character.charCodeAt(), ";") : character;
      }).join('');
    },
    decode(input) {
      input = "".concat(input);
      return input.replace(/&#(\d+);/g, function (matches, code) {
        return String.fromCharCode(code);
      });
    }
  };
  return entity;
});
