define('core/timer',[],function () {
  'use strict';
  function timerFactory(config) {
    var initConfig = config || {};
    var begin = now();
    var last = begin;
    var duration = initConfig.startDuration || 0;
    var state = {};
    var disableAutoStart = false === initConfig.autoStart;
    var timer = {
      start: function start(startDuration) {
        begin = now();
        last = begin;
        duration = startDuration || 0;
        state.running = true;
        state.started = true;
        return this;
      },
      tick: function tick() {
        var timestamp = now();
        var elapsed;
        if (state.running) {
          elapsed = timestamp - last;
          last = timestamp;
        }
        return elapsed;
      },
      pause: function pause() {
        if (state.running) {
          duration += now() - begin;
          state.running = false;
        }
        return this;
      },
      resume: function resume() {
        if (!state.running) {
          begin = now();
          last = begin;
          state.started = true;
          state.running = true;
        }
        return this;
      },
      stop: function stop() {
        if (state.running) {
          duration += now() - begin;
        }
        state.running = false;
        state.started = false;
        return this;
      },
      getDuration: function getDuration() {
        if (state.running) {
          return duration + (now() - begin);
        }
        return duration;
      },
      is: function is(stateName) {
        return !!state[stateName];
      },
      add: function add(time) {
        time = parseFloat(time);
        duration += time;
        last -= time;
        return this;
      },
      sub: function sub(time) {
        time = parseFloat(time);
        duration -= time;
        last += time;
        return this;
      }
    };
    function now() {
      return window.performance.now();
    }
    if (!disableAutoStart) {
      timer.start(initConfig.startDuration);
    }
    return timer;
  }
  return timerFactory;
});
