define('ui/mediaplayer/utils/reminder',[],function () {
  'use strict';
  function reminderManagerFactory() {
    var running = false;
    var last = 0;
    var reminders = new Map();
    var stopReminder = state => {
      if (state && state.timeout) {
        clearTimeout(state.timeout);
        state.timeout = null;
      }
    };
    var stopAllReminders = () => reminders.forEach(stopReminder);
    var startAllReminders = () => {
      reminders.forEach((state, reminder) => {
        stopReminder(state);
        state.timeout = setTimeout(reminder, state.delay);
      });
    };
    return {
      get running() {
        return running;
      },
      get elapsed() {
        if (!running) {
          return 0;
        }
        return performance.now() - last;
      },
      start() {
        running = true;
        last = performance.now();
        startAllReminders();
        return this;
      },
      stop() {
        running = false;
        stopAllReminders();
        return this;
      },
      remind(cb, delay) {
        if ('function' === typeof cb && delay) {
          stopReminder(reminders.get(cb));
          reminders.set(cb, {
            delay
          });
        }
        return this;
      },
      forget(cb) {
        if ('undefined' !== typeof cb) {
          stopReminder(reminders.get(cb));
          reminders.delete(cb);
        } else {
          stopAllReminders();
          reminders.clear();
        }
        return this;
      }
    };
  }
  return reminderManagerFactory;
});
